/**
 * Verification Phase 1b: every algorithm in the JSON generated by the SCDB
 * parser must SOLVE its case (not just be legal notation).
 *
 * Criteria (validated with manual tests on a real cube, 2026-08-06):
 *
 *   - OLL:  setup + alg → the last layer ends ORIENTED (U face all U) and F2L
 *           intact. An OLL alg does NOT leave the cube solved — it leaves the
 *           LL permuted. A single global rotation at the end is tolerated.
 *
 *   - PLL:  setup + alg → solved cube, tolerating a final AUF (U/U2/U') and a
 *           global rotation (including compounds like y'x for algs that rotate).
 *
 *   - COLL/CMLL: setup + alg → the 4 LL corners end solved (home + oriented)
 *           and F2L intact — only EPLL/LSE remains, which is exactly what the
 *           set promises. WV: same criterion as OLL (LL oriented + F2L).
 *   *   - F2L/AF2L: setup + alg → the case PAIR ends at home. The pair is NOT
   *           always "the FR slot pieces": in advanced cases the pair may be
   *           trapped in the slot (trapped corner / trapped edge) and belong to
   *           ANOTHER slot (the user confirmed by hand: in AF2L 2 the blue-red
   *           pair sits in FR and its home is BL). The identification rule,
   *           derived from the setups and validated on the cube:
 *             - if the corner in DFR is a displaced D-layer piece →
 *               trapped-corner: pair = {that corner, its edge}
 *             - else, if the edge in FR is a displaced D/E-layer piece →
 *               trapped-edge: pair = {that edge, its corner}
 *             - else → basic case: pair = slot pieces (DFR + FR).
 *           A slot pre-rotation (y/y2/y') and a final alg rotation are
 *           tolerated. "Reduction" algs (move the pair to the U layer without
 *           solving it) fail this criterion on purpose — they are audited
 *           separately.
 *
 *   - CLS/SV (last-slot sets, added 2026-08-06): setup + alg → F2L intact and
 *           the last layer fully ORIENTED (U face all U) — same as OLL. On SCDB
 *           most of these algs actually SOLVE the cube from their setup (they
 *           are full last-slot+LL solutions), which implies the OLL state, so
 *           the OLL criterion is the strict superset that validates both.
 *           The 2 CLS cases whose algs do neither (CLS FRU23, CLS RFU23) fail
 *           verification on purpose (SCDB data quirk, same class as the known
 *           PLL Ub one) and are excluded from the seeds.
 *
 *   - ELL/AntiPLL: setup + alg → solved cube (ELL solves the LL edges from a
 *           corners-solved setup; AntiPLL algs solve their PLL-named cases),
 *           tolerating a final AUF and whole-cube rotation — same as PLL.
 *
 *   - FRUF ("F <R,U> F'"): NOT verified — excluded from the seed catalog.
 *           Empirical audit (2026-08-06): only 6/42 cases have an alg that
 *           solves the case; the rest leave F2L solved but the last layer in
 *           inconsistent states (neither OLL-oriented nor solved), and the
 *           inverse-alg hypothesis is rejected too. The algs are user-submitted
 *           "F [RU-gen] F' tricks" without a solve guarantee, so they fail the
 *           plan's "every alg solves its case" rule and the dump/JSON is kept
 *           as audit trail only.
 *
 * The test writes the full report to
 *   pruebas/generated/verification-report.json
 * and prints a console summary.
 *
 * REGENERATION CONTRACT: the seed files
 * (packages/algorithm-db/src/seed/cfop-*.ts, generated by
 * pruebas/scripts/generate_seed_catalog.py) are filtered by this report's
 * pass/fail verdicts. Whenever the CUBE ALGEBRA changes (CubeState /
 * FaceletStringConverter / caseGenerator — e.g. commit cfe9044 added
 * extended-move support and flipped verdicts for S/E/z' algs), this report's
 * verdicts change and the seed MUST be regenerated, in this order:
 *   1. npx vitest run packages/algorithm-db/src/__tests__/scdb-dump-seed-catalog.test.ts
 *      (refreshes pruebas/generated/seed-casedefs.json — REQUIRED so the
 *      generator keeps the stable case IDs user progress is keyed by;
 *      without it the generator falls back to the JSON caseDefs and the IDs
 *      change, breaking user progress).
 *   2. npx vitest run packages/algorithm-db/src/__tests__/scdb-alg-verification.test.ts
 *      (writes this report).
 *   3. python pruebas/scripts/generate_seed_catalog.py
 * The seed-catalog suite (scdb-seed-catalog.test.ts) enforces the invariant
 * and fails loudly if the seed drifts from the report.
 *
 * CONFIRMED SCDB DATA QUIRKS (not parser bugs — checked against the raw web
 * notation and manual tests on a real cube):
 *   - PLL Ub, alternative `R2 U R U R' U' R3 U' R' U R'`: book Ub but needs a
 *     leading `y2` for this setup (the next alternative on the page DOES carry
 *     it). Without the y2 it leaves a Z-perm. NOTE: the `R3` token is invalid
 *     under MOVE_RE, so since 2026-08-06 it is excluded by the token filter
 *     below (and dropped from the seeds) instead of being verified-and-failed.
 *   - PLL T, alternative `l b d' L' U' F U2 L' U' L' U L U' f' S M r u E U' R'`
 *     (expanded in the JSON): does not solve the T setup as listed.
 *   - SV 7, alternative `R U2' R' U R U' R' …` (the same 9-move sequence
 *     repeated 4×): a copy-paste artifact that never solves — fails
 *     verification and is excluded from the seeds.
 *   - The parser normalizes `R2'`→`R2` / `M2'`→`M2` / `U2'`→`U2` on purpose
 *     (a 180° turn is identical either way) and expands wide moves replicating
 *     expandWideMoves() — physically equivalent.
 *
 * Run: npx vitest run packages/algorithm-db/src/__tests__/scdb-alg-verification.test.ts
 */

import { describe, it, expect } from "vitest";
import { readFileSync, existsSync, writeFileSync, mkdirSync } from "fs";
import { resolve, dirname } from "path";
import { CubeState, FaceletStringConverter } from "@cubeforge/math-core";
import { CaseStateGenerator } from "../caseGenerator";

// ─── Types ─────────────────────────────────────────────────────────────────

interface GenAlg { moves: string[]; notes?: string | null }
interface GenCase { caseDef: { caseNumber: string; setupScramble: string }; algorithms: GenAlg[] }
interface GenFile { source: string; set: string; cases: GenCase[] }

type Status = "exact" | "auf" | "rotated" | "fail";

interface AlgResult {
  set: string;
  caseNumber: string;
  slot: string;
  moves: string;
  status: Status;
  detail?: string;
}

const GENERATED: Record<string, string> = {
  pll: resolve(__dirname, "../../../../pruebas/generated/scdb-pll.json"),
  oll: resolve(__dirname, "../../../../pruebas/generated/scdb-oll.json"),
  // F2L/AdvancedF2L: the seed is generated from the FUSED dumps
  // (fase5-fuse.ts: SCDB + BirdF2L), so the verify gate runs
  // against those — every alg that lands in the seed must solve its case.
  af2l: resolve(__dirname, "../../../../pruebas/generated/scdb-af2l-fused.json"),
  f2l: resolve(__dirname, "../../../../pruebas/generated/scdb-f2l-fused.json"),
  coll: resolve(__dirname, "../../../../pruebas/generated/scdb-coll.json"),
  cmll: resolve(__dirname, "../../../../pruebas/generated/scdb-cmll.json"),
  wv: resolve(__dirname, "../../../../pruebas/generated/scdb-wv.json"),
  // CFOP sets added 2026-08-06 (non-AJAX SCDB dumps). FRUF is intentionally
  // NOT here: its algs do not satisfy the solve criterion (see header).
  cls: resolve(__dirname, "../../../../pruebas/generated/scdb-cls.json"),
  sv: resolve(__dirname, "../../../../pruebas/generated/scdb-sv.json"),
  ell: resolve(__dirname, "../../../../pruebas/generated/scdb-ell.json"),
  antipll: resolve(__dirname, "../../../../pruebas/generated/scdb-antipll.json"),
};
const REPORT_PATH = resolve(__dirname, "../../../../pruebas/generated/verification-report.json");

const hasAll = Object.values(GENERATED).every((p) => existsSync(p));

// ─── Geometry / facelets (Kociemba, exact from FaceletStringConverter) ──

const cornerFacelet = [[8, 9, 20], [6, 18, 38], [0, 36, 47], [2, 45, 11], [29, 26, 15], [27, 44, 24], [33, 53, 42], [35, 17, 51]];
const edgeFacelet = [[5, 10], [7, 19], [3, 37], [1, 46], [32, 16], [28, 25], [30, 43], [34, 52], [23, 12], [21, 41], [50, 39], [48, 14]];
const CCOL = [["U", "R", "F"], ["U", "F", "L"], ["U", "L", "B"], ["U", "B", "R"], ["D", "F", "R"], ["D", "L", "F"], ["D", "B", "L"], ["D", "R", "B"]];
const ECOL = [["U", "R"], ["U", "F"], ["U", "L"], ["U", "B"], ["D", "R"], ["D", "F"], ["D", "L"], ["D", "B"], ["F", "R"], ["F", "L"], ["B", "L"], ["B", "R"]];
const F2L_CORNERS = [4, 5, 6, 7];
const F2L_EDGES = [4, 5, 6, 7, 8, 9, 10, 11];
const MATE_EDGE_OF_CORNER = [8, 9, 10, 11, 8, 9, 10, 11];
// -1 for U edges (0-3, never a case pair); D edges 4-7 → their D-layer corner
// (DR→DRB, DF→DFR, DL→DLF, DB→DBL); E edges 8-11 → the slot corner.
const MATE_CORNER_OF_EDGE = [-1, -1, -1, -1, 7, 4, 5, 6, 4, 5, 6, 7];

const flOf = (s: CubeState) => FaceletStringConverter.toFaceletString(s);
const SOLVED_FL = flOf(new CubeState());

function cubieHome(kind: "c" | "e", pos: number, fl: string): number {
  const idxs = kind === "c" ? cornerFacelet[pos] : edgeFacelet[pos];
  const cols = idxs.map((i) => fl[i]).slice().sort().join("");
  const table = kind === "c" ? CCOL : ECOL;
  return table.findIndex((c) => c.slice().sort().join("") === cols);
}

/** Identifies the case pair (rule validated with manual tests). */
function identifyPair(fl: string): { kind: string; homeC: number; homeE: number } {
  const c = cubieHome("c", 4, fl); // cubie at DFR (FR slot)
  const e = cubieHome("e", 8, fl); // cubie at FR (edge)
  if (c >= 4 && c !== 4) return { kind: "trapped-corner", homeC: c, homeE: MATE_EDGE_OF_CORNER[c] };
  if (e >= 4 && e !== 8) return { kind: "trapped-edge", homeC: MATE_CORNER_OF_EDGE[e], homeE: e };
  return { kind: "basic", homeC: 4, homeE: 8 };
}

const SINGLE = ["", "y", "y2", "y'", "x", "x2", "x'", "z", "z2", "z'"];
const COMPOUND = ["y' x", "x y'", "y x'", "x' y", "z y", "y z", "x z", "z x", "y2 x", "x y2", "y2 z", "z y2"];
const ALL_POSTS = [...SINGLE, ...COMPOUND];
const apply = (s: CubeState, moves: string) => {
  for (const tok of moves.split(/\s+/).filter(Boolean)) s.applySequence(tok);
};

function pairHome(fl: string, homeC: number, homeE: number): boolean {
  return (
    cornerFacelet[homeC].every((i, k) => fl[i] === SOLVED_FL[cornerFacelet[homeC][k]]) &&
    edgeFacelet[homeE].every((i, k) => fl[i] === SOLVED_FL[edgeFacelet[homeE][k]])
  );
}

// ─── Verifiers ─────────────────────────────────────────────────────────

function verifyF2L(caseDef: GenCase["caseDef"], alg: GenAlg): AlgResult {
  const moves = alg.moves.join(" ");
  const s = CaseStateGenerator.generateFromScramble(caseDef.setupScramble);
  const pair = identifyPair(flOf(s));
  for (const slotRot of ["", "y", "y2", "y'"]) {
    const s0 = s.clone();
    if (slotRot) s0.applySequence(slotRot);
    for (const post of ALL_POSTS) {
      const t = s0.clone();
      t.applySequence(moves);
      apply(t, post);
      if (pairHome(flOf(t), pair.homeC, pair.homeE)) {
        return { set: "", caseNumber: caseDef.caseNumber, slot: (alg.notes ?? "").replace("Slot: ", "") || "?", moves, status: "exact", detail: `${slotRot || "∅"}→${post || "∅"} (${pair.kind})` };
      }
    }
  }
  return { set: "", caseNumber: caseDef.caseNumber, slot: (alg.notes ?? "").replace("Slot: ", "") || "?", moves, status: "fail" };
}

function verifyOll(caseDef: GenCase["caseDef"], alg: GenAlg): AlgResult {
  const moves = alg.moves.join(" ");
  const s = CaseStateGenerator.generateFromScramble(caseDef.setupScramble);
  // Simple rotations only: an OLL alg never rotates the frame with a compound
  // rotation (that would put the LL on a side face, not an OLL state).
  for (const post of SINGLE) {
    const t = s.clone();
    t.applySequence(moves);
    apply(t, post);
    const fl = flOf(t);
    const uOk = fl.slice(0, 9).split("").every((ch) => ch === "U");
    const f2lOk =
      F2L_CORNERS.every((p) => cornerFacelet[p].every((i, k) => fl[i] === SOLVED_FL[cornerFacelet[p][k]])) &&
      F2L_EDGES.every((p) => edgeFacelet[p].every((i, k) => fl[i] === SOLVED_FL[edgeFacelet[p][k]]));
    if (uOk && f2lOk) return { set: "", caseNumber: caseDef.caseNumber, slot: "—", moves, status: "exact", detail: post || "exact" };
  }
  return { set: "", caseNumber: caseDef.caseNumber, slot: "—", moves, status: "fail" };
}

function verifyPll(caseDef: GenCase["caseDef"], alg: GenAlg): AlgResult {
  const moves = alg.moves.join(" ");
  const s = CaseStateGenerator.generateFromScramble(caseDef.setupScramble);
  for (const auf of ["", "U", "U2", "U'"]) {
    for (const post of ALL_POSTS) {
      const t = s.clone();
      t.applySequence(moves + (auf ? " " + auf : ""));
      apply(t, post);
      if (t.isSolved()) return { set: "", caseNumber: caseDef.caseNumber, slot: "—", moves, status: "exact", detail: `${auf || "∅"}+${post || "∅"}` };
    }
  }
  return { set: "", caseNumber: caseDef.caseNumber, slot: "—", moves, status: "fail" };
}

// COLL/CMLL: after setup+alg the 4 LL corners are solved (home + oriented) and
// F2L is intact — only EPLL (COLL) or LSE (CMLL) remains, which is exactly
// what the set promises. A final U-layer AUF is tolerated (solved corners may
// rotate with the U layer).
function verifyCornersOnly(caseDef: GenCase["caseDef"], alg: GenAlg): AlgResult {
  const moves = alg.moves.join(" ");
  const s = CaseStateGenerator.generateFromScramble(caseDef.setupScramble);
  for (const auf of ["", "U", "U2", "U'"])
    for (const post of ALL_POSTS) {
      const t = s.clone();
      t.applySequence(moves + (auf ? " " + auf : ""));
      apply(t, post);
      const fl = flOf(t);
      const cornersOk = [0, 1, 2, 3].every((p) => cornerFacelet[p].every((i, k) => fl[i] === SOLVED_FL[cornerFacelet[p][k]]));
      const f2lOk =
        F2L_CORNERS.every((p) => cornerFacelet[p].every((i, k) => fl[i] === SOLVED_FL[cornerFacelet[p][k]])) &&
        F2L_EDGES.every((p) => edgeFacelet[p].every((i, k) => fl[i] === SOLVED_FL[edgeFacelet[p][k]]));
      if (cornersOk && f2lOk) return { set: "", caseNumber: caseDef.caseNumber, slot: "—", moves, status: "exact", detail: `${auf || "∅"}+${post || "∅"}` };
    }
  return { set: "", caseNumber: caseDef.caseNumber, slot: "—", moves, status: "fail" };
}

// ─── Suite ─────────────────────────────────────────────────────────────────

describe.runIf(hasAll)("SCDB Import: every algorithm solves its case", () => {
  // Verifies ~2300 algs with the solver — takes several seconds, more when
  // running in parallel with the rest of the suite. Wide timeout on purpose.
  it("verifies all algorithms and writes the report", () => {
    const allResults: AlgResult[] = [];

    // Algs with invalid move tokens (e.g. SCDB typo "U3' F3" on FRUF 2, which
    // never reaches the seeds — generate_seed_catalog drops them via MOVE_RE)
    // are skipped so the verifier does not crash on them.
    const VALID_MOVE = /^([RLUDFB]w?|[rludfbMES]|[xyz])(2|'|\u2032)?$/;
    const validAlgs = (algs: GenAlg[]) => algs.filter((a) => a.moves.every((m) => VALID_MOVE.test(m)));

    for (const [key, label, verifier] of [
      ["pll", "PLL", verifyPll],
      ["oll", "OLL", verifyOll],
      ["af2l", "AdvancedF2L", verifyF2L],
      ["f2l", "F2L", verifyF2L],
      ["coll", "COLL", verifyCornersOnly],
      ["cmll", "CMLL", verifyCornersOnly],
      ["wv", "WV", verifyOll],
      ["cls", "CLS", verifyOll],
      ["sv", "SV", verifyOll],
      ["ell", "ELL", verifyPll],
      ["antipll", "AntiPLL", verifyPll],
    ] as const) {
      const gen = JSON.parse(readFileSync(GENERATED[key], "utf-8")) as GenFile;
      const results = gen.cases.flatMap((c) => validAlgs(c.algorithms).map((a) => ({ ...verifier(c.caseDef, a), set: label })));
      allResults.push(...results);

      const byStatus = groupBy(results, (r) => r.status);
      console.log(`\n=== ${label}: ${results.length} algs ===`);
      console.log(`  PASS: ${results.length - (byStatus.fail?.length ?? 0)} | FAIL: ${byStatus.fail?.length ?? 0}`);
      if (byStatus.fail) {
        console.log("  FAILURES (audit in the report):");
        for (const f of byStatus.fail) console.log(`    ${f.caseNumber} [${f.slot}] ${f.moves}`);
      }
    }

    // Full report to disk (pruebas/ is gitignored).
    const summary = summarize(allResults);
    mkdirSync(dirname(REPORT_PATH), { recursive: true });
    writeFileSync(REPORT_PATH, JSON.stringify({ summary, results: allResults }, null, 1), "utf-8");
    console.log(`\nReport written to ${REPORT_PATH}`);

    const total = allResults.length;
    const passed = allResults.filter((r) => r.status !== "fail").length;
    console.log(`TOTAL: ${passed}/${total} (${(100 * passed / total).toFixed(2)}%)`);

    // CMLL (Roux) has 39 community algs that do not solve their setup as SCDB
    // lists them (they leave the DF edge — part of the Roux block — out of
    // place). It's an SCDB data issue, not a verifier issue, and does not
    // affect CFOP. It is reported but excluded from the threshold:
    const cfop = allResults.filter((r) => r.set !== "CMLL");
    const cfopPassed = cfop.filter((r) => r.status !== "fail").length;
    console.log(`CFOP (without CMLL): ${cfopPassed}/${cfop.length} (${(100 * cfopPassed / cfop.length).toFixed(2)}%)`);
    expect(cfopPassed / cfop.length).toBeGreaterThan(0.98);
  }, 60_000);
});

function groupBy<T>(arr: T[], key: (t: T) => string): Record<string, T[]> {
  const out: Record<string, T[]> = {};
  for (const t of arr) (out[key(t)] ??= []).push(t);
  return out;
}

function summarize(results: AlgResult[]) {
  const out: Record<string, { total: number; pass: number; fail: number; failures: AlgResult[] }> = {};
  for (const r of results) {
    out[r.set] ??= { total: 0, pass: 0, fail: 0, failures: [] };
    out[r.set].total++;
    if (r.status === "fail") { out[r.set].fail++; out[r.set].failures.push(r); }
    else out[r.set].pass++;
  }
  return out;
}
